class CanvasBase(QWidget):
    """Shared canvas scaffolding: scaling, HUD, overlays, particles, trail."""

    def __init__(self):
        super().__init__()
        self.fr = None
        self.trail = []
        self.particles = []
        self._episode = None
        self._was_dead = False
        rng = random.Random(7)
        self.stars = [(rng.uniform(0, 480), rng.uniform(0, 320),
                       rng.uniform(1.0, 2.4), rng.randint(40, 170))
                      for _ in range(90)]
        self.setMinimumSize(480, 320)

    def burst(self, cx, cy, colors=None, n=18):
        colors = colors or ("#00e5ff", "#8ef9ff", "#ffffff", "#ffd54f")
        self.particles = [(cx + math.cos(a := random.uniform(0, 2 * math.pi))
                           * random.uniform(8, 52),
                           cy + math.sin(a) * random.uniform(8, 52),
                           random.uniform(2.5, 6.5), random.choice(colors))
                          for _ in range(n)]

    def _begin(self, fr):
        if fr.get("episode") != self._episode:
            self._episode = fr.get("episode")
            self.trail.clear()
            self.particles.clear()
            self._was_dead = False

    def _end(self, fr):
        self._was_dead = bool(fr.get("dead"))
        self.fr = fr
        self.update()

    def set_frame(self, fr):
        raise NotImplementedError

    def _draw(self, p, W, H):
        raise NotImplementedError

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)
        W, H = 480, 320
        s = min(self.width() / W, self.height() / H)
        p.translate((self.width() - W * s) / 2, (self.height() - H * s) / 2)
        p.scale(s, s)
        p.setClipRect(QRectF(0, 0, W, H))
        if self.fr is None:
            self._placeholder(p, W, H)
        else:
            self._draw(p, W, H)

    def draw_particles(self, p):
        for x, y, s, col in self.particles:
            p.setPen(Qt.NoPen)
            p.setBrush(QColor(col))
            p.drawRect(QRectF(x - s / 2, y - s / 2, s, s))

    def hud(self, p, W, score, episode, right_text=None):
        p.setFont(QFont("Arial", 21, QFont.Bold))
        p.setPen(QColor(0, 0, 0, 120))
        p.drawText(QRectF(1, 9, W, 32), Qt.AlignHCenter | Qt.AlignTop, str(score))
        p.setPen(QColor("white"))
        p.drawText(QRectF(0, 8, W, 32), Qt.AlignHCenter | Qt.AlignTop, str(score))
        p.setFont(QFont("Arial", 10, QFont.Bold))
        p.setPen(QColor(0, 0, 0, 120))
        p.drawText(QPointF(11, 17), f"Attempt {episode}")
        p.setPen(QColor("white"))
        p.drawText(QPointF(10, 16), f"Attempt {episode}")
        if right_text:
            p.setPen(QColor(0, 0, 0, 120))
            p.drawText(QRectF(W - 129, 9, 120, 20), Qt.AlignRight, right_text)
            p.setPen(QColor("white"))
            p.drawText(QRectF(W - 130, 8, 120, 20), Qt.AlignRight, right_text)

    def crash_overlay(self, p, W, H):
        p.fillRect(QRectF(0, 0, W, H), QColor(200, 30, 30, 55))
        p.setFont(QFont("Arial", 24, QFont.Bold))
        p.setPen(QColor(0, 0, 0, 130))
        p.drawText(QRectF(1, H / 2 - 69, W, 40), Qt.AlignCenter, "CRASHED!")
        p.setPen(QColor("white"))
        p.drawText(QRectF(0, H / 2 - 70, W, 40), Qt.AlignCenter, "CRASHED!")

    def _placeholder(self, p, W, H):
        grad = QLinearGradient(0, 0, 0, H)
        grad.setColorAt(0.0, QColor("#0d0f1c"))
        grad.setColorAt(1.0, QColor("#181b33"))
        p.fillRect(QRectF(0, 0, W, H), QBrush(grad))
        p.setPen(Qt.NoPen)
        for x, y, s, a in self.stars:
            p.setBrush(QColor(255, 255, 255, a))
            p.drawRect(QRectF(x, y, s, s))
        p.setFont(QFont("Arial", 14, QFont.Bold))
        p.setPen(QColor(0, 0, 0, 120))
        p.drawText(QRectF(1, H / 2 - 35, W, 30), Qt.AlignCenter, GAME_TITLE)
        p.setPen(QColor("white"))
        p.drawText(QRectF(0, H / 2 - 36, W, 30), Qt.AlignCenter, GAME_TITLE)
        p.setFont(QFont("Arial", 11))
        p.setPen(QColor("#9fb3c8"))
        p.drawText(QRectF(0, H / 2, W, 26), Qt.AlignCenter, "Press ▶ Start training")
GAME_TITLE = "Space Invaders"
SAVE_DEFAULT = "invaders_dqn.pt"
GAME_HINT = ("Actions: 0=stay, 1=left, 2=right, 3=shoot, 4=left+shoot, "
             "5=right+shoot. Formation speeds up as it thins. +0.6..1.0/alien, "
             "+2 saucer, +3 wave, -0.05 drop, -1 life lost (3), instant "
             "game-over if they land.")


class SpaceInvadersEnv(gym.Env):
    metadata = {"render_modes": []}
    GAME_KEY = "invaders"
    OBS_DIM, N_ACTIONS = 69, 6
    W, H = 480, 320
    TOP = 40.0
    COLS, ROWS = 9, 5
    CELL_W, CELL_H = 30.0, 26.0
    ALIEN_W, ALIEN_H = 22.0, 16.0
    BASE_SPEED, MAX_SPEED, DROP = 0.55, 3.0, 14.0
    PLAYER_Y, PLAYER_W, PLAYER_SPEED = 292.0, 30.0, 4.5
    BULLET_SPEED, ALIEN_BULLET_SPEED = 9.0, 3.2
    MAX_ALIEN_BULLETS, COOLDOWN, LIVES = 3, 10, 3
    INVADER_Y, SHIELD_Y = 262.0, 246.0
    N_SHIELDS, SH_W, SH_H, SH_COLS, SH_ROWS = 4, 10.0, 8.0, 7, 4
    UFO_Y, UFO_W, UFO_SPEED = 36.0, 26.0, 2.2
    MAX_STEPS = 3600
    ROW_COLORS = ("#e040fb", "#40c4ff", "#69f0ae", "#ffee58", "#ff8a65")
    ROW_HW = (8.0, 9.0, 9.0, 10.0, 10.0)
    ROW_REWARD = (1.0, 0.9, 0.8, 0.7, 0.6)
    ROW_POINTS = (30, 25, 20, 15, 10)
    DROP_PENALTY = 0.05

    def __init__(self, render_mode=None):
        super().__init__()
        self.action_space = spaces.Discrete(self.N_ACTIONS)
        self.observation_space = spaces.Box(-1.5, 1.5, (self.OBS_DIM,), np.float32)

    def _new_formation(self):
        self.grid = [[True] * self.COLS for _ in range(self.ROWS)]
        self.total_aliens = self.COLS * self.ROWS
        self.n_alive = self.total_aliens
        self.form_x = (self.W - self.COLS * self.CELL_W) / 2.0
        self.form_y = self.TOP + 16.0 + min(self.wave - 1, 5) * 10.0
        self.fdir = 1
        self.fspeed = min(self.MAX_SPEED, self.BASE_SPEED + 0.1 * (self.wave - 1))
        self.fire_t = 40

    def _build_shields(self):
        self.shields = []
        for i in range(self.N_SHIELDS):
            cx = self.W * (i + 1) / (self.N_SHIELDS + 1)
            blocks = [[True] * self.SH_COLS for _ in range(self.SH_ROWS)]
            for r in range(self.SH_ROWS - 2, self.SH_ROWS):
                for c in range(self.SH_COLS // 2 - 1, self.SH_COLS // 2 + 2):
                    blocks[r][c] = False
            n = sum(sum(1 for v in row if v) for row in blocks)
            self.shields.append({"cx": cx, "blocks": blocks, "total": n, "alive": n})

    def _alien_xy(self, r, c):
        return (self.form_x + c * self.CELL_W + self.CELL_W / 2.0,
                self.form_y + r * self.CELL_H + self.CELL_H / 2.0)

    def _shield_hit(self, x, y, from_below):
        for sh in self.shields:
            half = self.SH_COLS * self.SH_W / 2.0
            if (abs(x - sh["cx"]) > half
                    or not (self.SHIELD_Y <= y
                            <= self.SHIELD_Y + self.SH_ROWS * self.SH_H)):
                continue
            c = int((x - (sh["cx"] - half)) // self.SH_W)
            r = int((y - self.SHIELD_Y) // self.SH_H)
            if (0 <= r < self.SH_ROWS and 0 <= c < self.SH_COLS
                    and sh["blocks"][r][c]):
                rows = (r, r - 1) if from_below else (r, r + 1)
                for rr in rows:
                    for cc in (c - 1, c, c + 1):
                        if (0 <= rr < self.SH_ROWS and 0 <= cc < self.SH_COLS
                                and sh["blocks"][rr][cc]):
                            sh["blocks"][rr][cc] = False
                            sh["alive"] -= 1
                return True
        return False

    def _obs(self):
        feats = [1.0 if self.grid[r][c] else 0.0
                 for r in range(self.ROWS) for c in range(self.COLS)]
        feats += [self.form_x / self.W, min(self.form_y / self.H, 1.5),
                  1.0 if self.fdir > 0 else 0.0,
                  min(self.fspeed / self.MAX_SPEED, 1.0)]
        feats.append(self.px / self.W)
        if self.pbullet is not None:
            feats += [1.0, self.pbullet["y"] / self.H]
        else:
            feats += [0.0, 0.0]
        bs = sorted(self.abullets, key=lambda b: self.PLAYER_Y - b["y"])[:3]
        for b in bs:
            feats += [(b["x"] - self.px) / self.W, (self.PLAYER_Y - b["y"]) / self.H]
        feats += [0.0, 0.0] * (3 - len(bs))
        for r in range(self.ROWS):
            alive = [c for c in range(self.COLS) if self.grid[r][c]]
            if alive:
                ax = min((self.form_x + c * self.CELL_W + self.CELL_W / 2
                          for c in alive), key=lambda v: abs(v - self.px))
                feats.append((ax - self.px) / self.W)
            else:
                feats.append(1.5)
        for sh in self.shields:
            feats.append(sh["alive"] / max(sh["total"], 1))
        if self.ufo is not None:
            feats += [1.0, (self.ufo["x"] - self.px) / self.W]
        else:
            feats += [0.0, 0.0]
        return np.array(feats, dtype=np.float32)

    def reset(self, *, seed=None, options=None):
        super().reset(seed=seed)
        self.wave = 1
        self.lives = self.LIVES
        self.score = self.steps = 0
        self.px = self.W / 2
        self.cool = 0
        self.pbullet = None
        self.abullets = []
        self.ufo = None
        self.ufo_t = int(self.np_random.integers(400, 700))
        self.fx = []
        self._new_formation()
        self._build_shields()
        return self._obs(), {}

    def step(self, action):
        self.steps += 1
        reward = 0.01
        terminated = False
        if action in (1, 4):
            self.px = max(self.PLAYER_W / 2 + 4, self.px - self.PLAYER_SPEED)
        elif action in (2, 5):
            self.px = min(self.W - self.PLAYER_W / 2 - 4, self.px + self.PLAYER_SPEED)
        if action >= 3 and self.cool == 0 and self.pbullet is None:
            self.pbullet = {"x": self.px, "y": self.PLAYER_Y - 14.0}
            self.cool = self.COOLDOWN
            reward -= 0.01
        self.cool = max(0, self.cool - 1)
        if self.n_alive > 0:
            self.form_x += self.fdir * self.fspeed
            alive_cols = [c for r in range(self.ROWS) for c in range(self.COLS)
                          if self.grid[r][c]]
            lo, hi = min(alive_cols), max(alive_cols)
            left = self.form_x + lo * self.CELL_W
            right = self.form_x + hi * self.CELL_W + self.CELL_W
            if (self.fdir > 0 and right > self.W - 6) or (self.fdir < 0 and left < 6):
                self.fdir *= -1
                self.form_y += self.DROP
                reward -= self.DROP_PENALTY
                bottom_row = max(r for r in range(self.ROWS) if any(self.grid[r]))
                if (self.form_y + bottom_row * self.CELL_H
                        + self.ALIEN_H / 2 >= self.INVADER_Y):
                    reward -= 1.0
                    self.fx.append(("bad", self.px, self.PLAYER_Y))
                    terminated = True
        if not terminated and self.pbullet is not None:
            b = self.pbullet
            b["y"] -= self.BULLET_SPEED
            if (self.ufo is not None
                    and abs(b["x"] - self.ufo["x"]) <= self.UFO_W / 2 + 2
                    and abs(b["y"] - self.UFO_Y) <= 10):
                reward += 2.0
                self.score += 200
                self.fx.append(("good", self.ufo["x"], self.UFO_Y))
                self.ufo = None
                self.pbullet = None
            else:
                hit = None
                for r in range(self.ROWS):
                    for c in range(self.COLS):
                        if not self.grid[r][c]:
                            continue
                        ax, ay = self._alien_xy(r, c)
                        if (abs(b["x"] - ax) <= self.ALIEN_W / 2 + 1
                                and abs(b["y"] - ay) <= self.ALIEN_H / 2 + 2):
                            if hit is None or ay > hit[2]:
                                hit = (r, c, ay)
                if hit is not None:
                    r, c, ay = hit
                    ax = self.form_x + c * self.CELL_W + self.CELL_W / 2
                    self.grid[r][c] = False
                    self.n_alive -= 1
                    reward += self.ROW_REWARD[r]
                    self.score += self.ROW_POINTS[r]
                    self.fx.append(("pop", ax, ay, self.ROW_COLORS[r]))
                    self.fspeed = min(self.MAX_SPEED,
                                      self.BASE_SPEED
                                      * (1 + 2.6 * (1 - self.n_alive / self.total_aliens))
                                      + 0.1 * (self.wave - 1))
                    self.pbullet = None
                elif self._shield_hit(b["x"], b["y"], from_below=True):
                    self.pbullet = None
                elif b["y"] < self.TOP - 6:
                    self.pbullet = None
        if self.n_alive == 0 and not terminated:
            self.wave += 1
            reward += 3.0
            self._new_formation()
            self._build_shields()
        if self.n_alive > 0 and not terminated:
            self.fire_t -= 1
            if self.fire_t <= 0 and len(self.abullets) < self.MAX_ALIEN_BULLETS:
                cols = [c for c in range(self.COLS)
                        if any(self.grid[r][c] for r in range(self.ROWS))]
                c = cols[int(self.np_random.integers(0, len(cols)))]
                r = max(rr for rr in range(self.ROWS) if self.grid[rr][c])
                ax, ay = self._alien_xy(r, c)
                self.abullets.append({"x": ax, "y": ay + self.ALIEN_H / 2})
                base = max(14, int(46 - 6 * self.wave
                                   - 18 * (1 - self.n_alive / self.total_aliens)))
                self.fire_t = base + int(self.np_random.integers(0, 12))
        if not terminated:
            for b in self.abullets:
                b["y"] += self.ALIEN_BULLET_SPEED
            if self.pbullet is not None:
                pb = self.pbullet
                for b in self.abullets:
                    if abs(b["x"] - pb["x"]) < 6 and abs(b["y"] - pb["y"]) < 9:
                        b["dead"] = True
                        self.fx.append(("pop", b["x"], b["y"], "#ffb300"))
                        self.pbullet = None
                        break
            self.abullets = [b for b in self.abullets
                             if not b.get("dead") and b["y"] < self.H]
            kept = []
            for b in self.abullets:
                if not self._shield_hit(b["x"], b["y"], from_below=False):
                    kept.append(b)
            self.abullets = kept
            for b in self.abullets:
                if (abs(b["x"] - self.px) < 17
                        and self.PLAYER_Y - 12 <= b["y"] <= self.PLAYER_Y + 4):
                    self.lives -= 1
                    reward -= 1.0
                    self.fx.append(("bad", self.px, self.PLAYER_Y))
                    self.abullets = []
                    if self.lives <= 0:
                        terminated = True
                    break
        if not terminated:
            if self.ufo is None:
                self.ufo_t -= 1
                if self.ufo_t <= 0:
                    d = 1 if self.np_random.random() < 0.5 else -1
                    self.ufo = {"x": -30.0 if d > 0 else self.W + 30.0,
                                "v": d * self.UFO_SPEED}
                    self.ufo_t = int(self.np_random.integers(500, 900))
            else:
                self.ufo["x"] += self.ufo["v"]
                if self.ufo["x"] < -40 or self.ufo["x"] > self.W + 40:
                    self.ufo = None
        return self._obs(), reward, terminated, self.steps >= self.MAX_STEPS, {"score": self.score}

    def get_frame(self):
        aliens = []
        for r in range(self.ROWS):
            for c in range(self.COLS):
                if self.grid[r][c]:
                    ax, ay = self._alien_xy(r, c)
                    aliens.append((ax, ay, r))
        shields = []
        for sh in self.shields:
            half = self.SH_COLS * self.SH_W / 2.0
            for r in range(self.SH_ROWS):
                for c in range(self.SH_COLS):
                    if sh["blocks"][r][c]:
                        shields.append((sh["cx"] - half + c * self.SH_W,
                                        self.SHIELD_Y + r * self.SH_H))
        fr = {"game": self.GAME_KEY, "px": self.px,
              "pbullet": None if self.pbullet is None
                         else (self.pbullet["x"], self.pbullet["y"]),
              "abullets": [(b["x"], b["y"]) for b in self.abullets],
              "aliens": aliens, "shields": shields,
              "ufo": None if self.ufo is None else self.ufo["x"],
              "phase": (self.steps // 14) % 2,
              "lives": self.lives, "wave": self.wave,
              "score": self.score, "steps": self.steps,
              "dead": False, "fx": self.fx}
        self.fx = []
        return fr


def _invader_sprite(p, x, y, hw, color, phase):
    p.setPen(Qt.NoPen)
    p.setBrush(QColor(color))
    p.drawRect(QRectF(x - hw, y - 6, 2 * hw, 8))
    p.drawRect(QRectF(x - hw + 3, y - 9, 2 * hw - 6, 3))
    p.setBrush(QColor("#0a0a14"))
    p.drawRect(QRectF(x - hw + 4, y - 5, 3, 3))
    p.drawRect(QRectF(x + hw - 7, y - 5, 3, 3))
    p.setBrush(QColor(color))
    if phase:
        p.drawRect(QRectF(x - hw, y + 2, 4, 5))
        p.drawRect(QRectF(x + hw - 4, y + 2, 4, 5))
        p.drawRect(QRectF(x - 2, y + 2, 4, 4))
    else:
        p.drawRect(QRectF(x - hw + 2, y + 2, 3, 4))
        p.drawRect(QRectF(x + hw - 5, y + 2, 3, 4))
        p.drawRect(QRectF(x - hw + 6, y + 2, 2 * hw - 12, 2))


class GameCanvas(CanvasBase):
    def set_frame(self, fr):
        if fr is None:
            self.fr = None
            self.update()
            return
        self._begin(fr)
        for fx in fr.get("fx", []):
            kind, x, y = fx[0], fx[1], fx[2]
            if kind == "good":
                self.burst(x, y, ("#ffd54f", "#9cff57", "#ffffff", "#9cff57"))
            elif kind == "bad":
                self.burst(x, y, ("#ff5252", "#ff8a65", "#ffffff", "#ffb300"))
            elif kind == "pop":
                self.burst(x, y, (fx[3], "#ffffff", fx[3], "#ffd54f"), n=10)
        if fr.get("dead") and not self._was_dead:
            self.burst(fr["px"], SpaceInvadersEnv.PLAYER_Y,
                       ("#69f0ae", "#ff5252", "#ffffff", "#ffd54f"))
        self._end(fr)

    def _draw(self, p, W, H):
        E = SpaceInvadersEnv
        fr = self.fr
        p.fillRect(QRectF(0, 0, W, H), QColor("#05060f"))
        p.setPen(Qt.NoPen)
        for x, y, s, a in self.stars:
            p.setBrush(QColor(255, 255, 255, a // 3))
            p.drawRect(QRectF(x, y, s, s))
        p.setPen(QPen(QColor(105, 240, 174, 200), 2))
        p.drawLine(QPointF(0, E.PLAYER_Y + 12), QPointF(W, E.PLAYER_Y + 12))
        p.setPen(Qt.NoPen)
        for bx, by in fr["shields"]:
            p.setBrush(QColor("#43a047"))
            p.drawRect(QRectF(bx, by, E.SH_W - 1, E.SH_H - 1))
        for ax, ay, r in fr["aliens"]:
            _invader_sprite(p, ax, ay, E.ROW_HW[r], E.ROW_COLORS[r], fr["phase"])
        if fr["ufo"] is not None:
            ux = fr["ufo"]
            p.setPen(QPen(QColor("#ff1744"), 2))
            p.setBrush(QColor("#e53935"))
            p.drawEllipse(QPointF(ux, E.UFO_Y), 14, 5.5)
            p.setPen(Qt.NoPen)
            p.setBrush(QColor("#ff8a80"))
            p.drawEllipse(QPointF(ux, E.UFO_Y - 4), 6, 4)
            p.setBrush(QColor("#ffe082"))
            for i in (-7, 0, 7):
                p.drawEllipse(QPointF(ux + i, E.UFO_Y + 2), 1.8, 1.8)
        if fr["pbullet"]:
            bx, by = fr["pbullet"]
            p.setBrush(QColor("#e8f5e9"))
            p.drawRect(QRectF(bx - 1.5, by - 5, 3, 10))
        step4 = fr["steps"] // 4
        p.setBrush(QColor("#ffb300"))
        for bx, by in fr["abullets"]:
            for i in range(3):
                off = 3 if (i + step4) % 2 == 0 else -3
                p.drawRect(QRectF(bx + off - 1.5, by - 6 + i * 5, 3, 4))
        if fr.get("dead"):
            self.draw_particles(p)
        else:
            px = fr["px"]
            p.setBrush(QColor("#69f0ae"))
            p.drawRect(QRectF(px - 15, E.PLAYER_Y - 4, 30, 10))
            p.drawRect(QRectF(px - 4, E.PLAYER_Y - 11, 8, 8))
            p.setBrush(QColor("#1b5e20"))
            p.drawRect(QRectF(px - 15, E.PLAYER_Y + 2, 30, 3))
        for i in range(fr["lives"]):
            lx = 16 + i * 26
            p.setBrush(QColor("#69f0ae"))
            p.drawRect(QRectF(lx - 8, H - 16, 16, 6))
            p.drawRect(QRectF(lx - 2, H - 21, 5, 5))
        self.hud(p, W, fr["score"], fr["episode"], right_text=f"Wave {fr['wave']}")
        if fr.get("dead"):
            self.crash_overlay(p, W, H)


def make_env():
    return SpaceInvadersEnv()


class QNet(nn.Module):
    def __init__(self, obs_dim, n_actions, hidden=128):
        super().__init__()
        self.body = nn.Sequential(
            nn.Linear(obs_dim, hidden), nn.ReLU(),
            nn.Linear(hidden, hidden), nn.ReLU(),
            nn.Linear(hidden, n_actions))

    def forward(self, x):
        return self.body(x)


class DQNAgent:
    def __init__(self, obs_dim, n_actions):
        self.n_actions = n_actions
        self.policy = QNet(obs_dim, n_actions).to(DEVICE)
        self.target = QNet(obs_dim, n_actions).to(DEVICE)
        self.sync_target()
        self.opt = torch.optim.Adam(self.policy.parameters(), lr=1e-3)
        self.buffer = deque(maxlen=50_000)
        self.gamma, self.batch, self.warmup = 0.99, 64, 1_000
        self.target_sync = 1_000
        self.eps_start, self.eps_end, self.eps_decay = 1.0, 0.05, 20_000
        self.total_steps = 0
        self._since_sync = 0

    @property
    def epsilon(self):
        t = min(self.total_steps, self.eps_decay)
        return self.eps_end + (self.eps_start - self.eps_end) * (1 - t / self.eps_decay)

    def sync_target(self):
        self.target.load_state_dict(self.policy.state_dict())

    def act(self, obs, greedy=False):
        if not greedy and random.random() < self.epsilon:
            return random.randrange(self.n_actions)
        with torch.no_grad():
            t = torch.as_tensor(obs, dtype=torch.float32, device=DEVICE).unsqueeze(0)
            return int(self.policy(t).argmax().item())

    def remember(self, s, a, r, s2, done):
        self.buffer.append((s, a, r, s2, done))

    def learn(self):
        if len(self.buffer) < self.warmup:
            return None
        batch = random.sample(self.buffer, self.batch)
        s, a, r, s2, d = map(np.asarray, zip(*batch))
        s = torch.as_tensor(s, dtype=torch.float32, device=DEVICE)
        a = torch.as_tensor(a, dtype=torch.int64, device=DEVICE).unsqueeze(1)
        r = torch.as_tensor(r, dtype=torch.float32, device=DEVICE)
        s2 = torch.as_tensor(s2, dtype=torch.float32, device=DEVICE)
        d = torch.as_tensor(d, dtype=torch.float32, device=DEVICE)
        q = self.policy(s).gather(1, a).squeeze(1)
        with torch.no_grad():
            target = r + self.gamma * self.target(s2).max(dim=1).values * (1 - d)
        loss = F.smooth_l1_loss(q, target)
        self.opt.zero_grad()
        loss.backward()
        nn.utils.clip_grad_norm_(self.policy.parameters(), 10.0)
        self.opt.step()
        self._since_sync += 1
        if self._since_sync >= self.target_sync:
            self.sync_target()
            self._since_sync = 0
        return float(loss.item())


class TrainingWorker(QThread):
    frame = Signal(object)
    stats = Signal(object)
    episode_done = Signal(int, float)
    logmsg = Signal(str)
    FRAME_DELAY_MS = 15

    def __init__(self, start_paused=False):
        super().__init__()
        self.env = make_env()
        self.agent = DQNAgent(self.env.OBS_DIM, self.env.N_ACTIONS)
        self.render_every = 1
        self.turbo = False
        self._paused = start_paused
        self._stop = False
        self._save_path = None
        self._load_path = None

    def toggle_pause(self):
        self._paused = not self._paused

    def stop_run(self):
        self._stop = True
        self._paused = False

    def request_save(self, path): self._save_path = path
    def request_load(self, path): self._load_path = path

    def run(self):
        try:
            self._train()
        except Exception as e:
            self.logmsg.emit(f"Training stopped with error: {e!r}")

    def _train(self):
        env = self.env
        episode, best = 0, 0
        recent = deque(maxlen=20)
        while not self._stop:
            while self._paused and not self._stop:
                self._process_requests()
                self.msleep(50)
            if self._stop:
                break
            episode += 1
            obs, _ = env.reset(seed=random.randrange(2**31 - 1))
            total_r, done = 0.0, False
            loss_sum, n_loss = 0.0, 0
            term = trunc = False
            while not done and not self._stop:
                self._process_requests()
                action = self.agent.act(obs)
                obs2, r, t_, tr_, _ = env.step(action)
                term, trunc = bool(t_), bool(tr_)
                done = term or trunc
                self.agent.remember(obs, action, r, obs2, float(term))
                obs = obs2
                total_r += r
                loss = self.agent.learn()
                self.agent.total_steps += 1
                if loss is not None:
                    loss_sum += loss
                    n_loss += 1
                if not self.turbo and env.steps % max(1, self.render_every) == 0:
                    fr = env.get_frame()
                    fr["episode"] = episode
                    self.frame.emit(fr)
                    self.msleep(self.FRAME_DELAY_MS)
                if env.steps % 500 == 0:
                    self._emit_stats(episode, best, recent, loss_sum, n_loss)
            if self._stop:
                break
            if not self.turbo:
                fr = env.get_frame()
                fr["episode"] = episode
                fr["dead"] = term and not fr.get("won", False)
                self.frame.emit(fr)
            recent.append(total_r)
            self.episode_done.emit(episode, total_r)
            if env.score > best:
                best = env.score
                self.logmsg.emit(f"Attempt {episode}: new best — score {best} "
                                 f"(reward {total_r:.1f})")
            self._emit_stats(episode, best, recent, loss_sum, n_loss)
        self.logmsg.emit("Training thread finished.")

    def _emit_stats(self, episode, best, recent, loss_sum, n_loss):
        self.stats.emit({
            "episode": episode, "steps": self.agent.total_steps,
            "score": self.env.score, "best": best,
            "epsilon": self.agent.epsilon,
            "avg_reward": sum(recent) / len(recent) if recent else 0.0,
            "loss": loss_sum / n_loss if n_loss else None,
            "buffer": len(self.agent.buffer)})

    def _process_requests(self):
        if self._load_path:
            path, self._load_path = self._load_path, None
            try:
                ckpt = torch.load(path, map_location=DEVICE)
                self.agent.policy.load_state_dict(ckpt["policy"])
                self.agent.sync_target()
                self.agent.total_steps = max(self.agent.total_steps,
                                             self.agent.eps_decay)
                self.logmsg.emit(f"Model loaded from {path} "
                                 f"(epsilon now {self.agent.epsilon:.2f}).")
            except Exception as e:
                self.logmsg.emit(f"Load failed: {e}")
        if self._save_path:
            path, self._save_path = self._save_path, None
            try:
                torch.save({"policy": self.agent.policy.state_dict(),
                            "steps": self.agent.total_steps}, path)
                self.logmsg.emit(f"Model saved to {path}.")
            except Exception as e:
                self.logmsg.emit(f"Save failed: {e}")


class RewardChart(QWidget):
    def __init__(self):
        super().__init__()
        self.rewards = []
        self.setMinimumHeight(140)

    def add(self, _episode, reward):
        self.rewards.append(reward)
        if len(self.rewards) > 3000:
            self.rewards = self.rewards[-3000:]
        self.update()

    def clear(self):
        self.rewards.clear()
        self.update()

    def paintEvent(self, _):
        p = QPainter(self)
        w, h = self.width(), self.height()
        p.fillRect(self.rect(), QColor("#15151f"))
        pad_l, pad_r, pad_t, pad_b = 48, 12, 18, 22
        p.setFont(QFont("Arial", 9))
        n = len(self.rewards)
        if n < 2:
            p.setPen(QColor("#55556a"))
            p.drawText(self.rect(), Qt.AlignCenter, "no data yet — start training")
            return
        rs = self.rewards
        k = min(20, n)
        c, ma = 0.0, []
        for i, r in enumerate(rs):
            c += r
            if i >= k:
                c -= rs[i - k]
            ma.append(c / min(i + 1, k))
        lo, hi = min(rs + ma), max(rs + ma)
        if hi - lo < 1e-9:
            hi = lo + 1
        m = (hi - lo) * 0.08
        lo, hi = lo - m, hi + m

        def X(i):
            return pad_l + (w - pad_l - pad_r) * i / (n - 1)

        def Y(v):
            return pad_t + (h - pad_t - pad_b) * (1 - (v - lo) / (hi - lo))

        p.setPen(QPen(QColor("#26263a"), 1))
        for f in (0.25, 0.5, 0.75):
            y = pad_t + (h - pad_t - pad_b) * f
            p.drawLine(QPointF(pad_l, y), QPointF(w - pad_r, y))
        if lo < 0 < hi:
            p.setPen(QPen(QColor("#3a3a55"), 1, Qt.DashLine))
            p.drawLine(QPointF(pad_l, Y(0)), QPointF(w - pad_r, Y(0)))
        p.setPen(QPen(QColor(100, 150, 255, 130), 1))
        p.drawPolyline(QPolygonF([QPointF(X(i), Y(v)) for i, v in enumerate(rs)]))
        p.setPen(QPen(QColor("#ffc107"), 2))
        p.drawPolyline(QPolygonF([QPointF(X(i), Y(v)) for i, v in enumerate(ma)]))
        p.setPen(QColor("#8a8aa0"))
        p.drawText(QPointF(6, pad_t + 6), f"{hi - m:.0f}")
        p.drawText(QPointF(6, h - pad_b), f"{lo + m:.0f}")
        p.drawText(QPointF(w - 180, h - 6), f"yellow: moving avg({k})   blue: raw")


class MainWindow(QMainWindow):
    def __init__(self):
        super().__init__()
        self.setWindowTitle(f"Neural {GAME_TITLE} — DQN Trainer")
        self.resize(1060, 660)
        self.worker = None
        self._paused = False

        central = QWidget()
        self.setCentralWidget(central)
        root = QHBoxLayout(central)
        root.setContentsMargins(10, 10, 10, 10)
        root.setSpacing(10)
        game_box = QGroupBox("Game")
        gv = QVBoxLayout(game_box)
        self.canvas = GameCanvas()
        gv.addWidget(self.canvas)
        root.addWidget(game_box, 1)
        right = QWidget()
        right.setFixedWidth(400)
        rv = QVBoxLayout(right)
        rv.setSpacing(8)
        root.addWidget(right)

        ctl = QGroupBox("Training")
        cg = QGridLayout(ctl)
        self.btn_start = QPushButton("▶  Start training")
        self.btn_start.setStyleSheet("font-weight: bold;")
        self.btn_start.clicked.connect(self.toggle_training)
        self.btn_reset = QPushButton("⟲  Reset")
        self.btn_reset.clicked.connect(self.reset_all)
        self.btn_save = QPushButton("Save model")
        self.btn_save.clicked.connect(self.save_model)
        self.btn_load = QPushButton("Load model")
        self.btn_load.clicked.connect(self.load_model)
        cg.addWidget(self.btn_start, 0, 0)
        cg.addWidget(self.btn_reset, 0, 1)
        cg.addWidget(self.btn_save, 1, 0)
        cg.addWidget(self.btn_load, 1, 1)
        speed_row = QHBoxLayout()
        speed_row.addWidget(QLabel("Render speed"))
        self.speed_slider = QSlider(Qt.Horizontal)
        self.speed_slider.setRange(1, 15)
        self.speed_slider.setValue(1)
        self.speed_slider.valueChanged.connect(self._on_speed)
        self.lbl_speed = QLabel("x1")
        self.lbl_speed.setFixedWidth(30)
        speed_row.addWidget(self.speed_slider)
        speed_row.addWidget(self.lbl_speed)
        cg.addLayout(speed_row, 2, 0, 1, 2)
        self.chk_turbo = QCheckBox("Turbo mode (train headless — no rendering)")
        self.chk_turbo.toggled.connect(self._on_turbo)
        cg.addWidget(self.chk_turbo, 3, 0, 1, 2)
        rv.addWidget(ctl)

        stats_box = QGroupBox("Telemetry")
        form = QFormLayout(stats_box)
        form.setLabelAlignment(Qt.AlignRight)
        self.lbl_episode, self.lbl_steps = QLabel("–"), QLabel("–")
        self.lbl_score, self.lbl_best = QLabel("–"), QLabel("–")
        self.lbl_eps, self.lbl_avg = QLabel("–"), QLabel("–")
        self.lbl_loss, self.lbl_buf = QLabel("–"), QLabel("–")
        form.addRow("Attempt:", self.lbl_episode)
        form.addRow("Env steps:", self.lbl_steps)
        form.addRow("Score (last):", self.lbl_score)
        form.addRow("Best:", self.lbl_best)
        form.addRow("Epsilon (explore):", self.lbl_eps)
        form.addRow("Avg reward (20 ep):", self.lbl_avg)
        form.addRow("Loss:", self.lbl_loss)
        form.addRow("Replay buffer:", self.lbl_buf)
        rv.addWidget(stats_box)

        chart_box = QGroupBox("Reward per attempt")
        cv = QVBoxLayout(chart_box)
        self.chart = RewardChart()
        cv.addWidget(self.chart)
        rv.addWidget(chart_box, 1)

        self.log_box = QPlainTextEdit()
        self.log_box.setReadOnly(True)
        self.log_box.setMaximumHeight(84)
        rv.addWidget(self.log_box)

        self.statusBar().showMessage(
            f"Device: {DEVICE}  •  PyTorch {torch.__version__}  "
            f"•  Gymnasium {gym.__version__}")
        self.log(GAME_HINT)
        self.log("Tip: use Turbo for fast headless training, then untick to "
                 "watch the agent play.")

    def log(self, msg):
        self.log_box.appendPlainText(msg)

    def _spawn_worker(self, start_paused=False):
        w = TrainingWorker(start_paused=start_paused)
        w.frame.connect(self.canvas.set_frame)
        w.episode_done.connect(self.chart.add)
        w.stats.connect(self.on_stats)
        w.logmsg.connect(self.log)
        w.render_every = self.speed_slider.value()
        w.turbo = self.chk_turbo.isChecked()
        w.start()
        self._paused = start_paused
        self.btn_start.setText("▶  Resume" if start_paused else "⏸  Pause")
        return w

    def toggle_training(self):
        if self.worker is None:
            self.worker = self._spawn_worker()
            self.log("Training started.")
        else:
            self.worker.toggle_pause()
            self._paused = not self._paused
            self.btn_start.setText("▶  Resume" if self._paused else "⏸  Pause")
            self.log("Paused." if self._paused else "Resumed.")

    def reset_all(self):
        if self.worker is not None:
            self.worker.stop_run()
            self.worker.wait(3000)
            self.worker = None
        self.canvas.set_frame(None)
        self.chart.clear()
        for lbl in (self.lbl_episode, self.lbl_steps, self.lbl_score, self.lbl_best,
                    self.lbl_eps, self.lbl_avg, self.lbl_loss, self.lbl_buf):
            lbl.setText("–")
        self._paused = False
        self.btn_start.setText("▶  Start training")
        self.log("Reset — agent and environment re-initialized.")

    def on_stats(self, d):
        self.lbl_episode.setText(str(d["episode"]))
        self.lbl_steps.setText(f"{d['steps']:,}")
        self.lbl_score.setText(str(d["score"]))
        self.lbl_best.setText(str(d["best"]))
        self.lbl_eps.setText(f"{d['epsilon']:.3f}")
        self.lbl_avg.setText(f"{d['avg_reward']:.1f}")
        self.lbl_loss.setText("–" if d["loss"] is None else f"{d['loss']:.4f}")
        self.lbl_buf.setText(f"{d['buffer']:,}")

    def _on_speed(self, v):
        self.lbl_speed.setText(f"x{v}")
        if self.worker:
            self.worker.render_every = v

    def _on_turbo(self, on):
        if self.worker:
            self.worker.turbo = on

    def save_model(self):
        if self.worker is None:
            QMessageBox.information(self, "Save model",
                                    "Start training first — there is no model "
                                    "to save yet.")
            return
        path, _ = QFileDialog.getSaveFileName(self, "Save model", SAVE_DEFAULT,
                                              "PyTorch model (*.pt)")
        if path:
            self.worker.request_save(path)

    def load_model(self):
        path, _ = QFileDialog.getOpenFileName(self, "Load model", "",
                                              "PyTorch model (*.pt)")
        if not path:
            return
        if self.worker is None:
            self.worker = self._spawn_worker(start_paused=True)
            self.log("Worker created (paused) — press Resume to watch it play.")
        self.worker.request_load(path)

    def closeEvent(self, event):
        if self.worker is not None:
            self.worker.stop_run()
            self.worker.wait(3000)
        event.accept()


def main():
    app = QApplication(sys.argv)
    app.setStyle("Fusion")
    win = MainWindow()
    win.show()
    sys.exit(app.exec())


if __name__ == "__main__":
    main()
